import { useState, useEffect } from 'react';
import { getAllSubmissions } from '../apis/adminApi';
import { useNavigate } from 'react-router-dom';

function Skeleton({ w='100%', h=16, radius=6, style={} }) {
  return <div style={{ width:w, height:h, borderRadius:radius, background:'linear-gradient(90deg,var(--skeleton-a,#E2E8F0) 25%,var(--skeleton-b,#F1F5F9) 50%,var(--skeleton-a,#E2E8F0) 75%)', backgroundSize:'200% 100%', animation:'shimmer 1.4s infinite', ...style }}/>;
}

const sMap = { Pending:'b-pending','In Review':'b-review',Approved:'b-approved',Failed:'b-failed' };
const Badge = ({ s }) => <span className={`badge ${sMap[s]||'b-pending'}`}>{s}</span>;

const COLORS = ['#6C63FF','#FF6584','#43E97B','#FA8231','#E74C3C','#3498DB','#9B59B6','#1ABC9C','#E67E22','#2ECC71'];
function getInitials(name) { if (!name) return '?'; return name.split(' ').map(w=>w[0]).join('').toUpperCase().slice(0,2); }
function normalizeStatus(s) {
  if (!s) return 'Pending';
  const m = { pending:'Pending', approved:'Approved', rejected:'Failed', failed:'Failed', 'in-review':'In Review', 'in_review':'In Review' };
  return m[s] || s;
}

function UserModal({ u, onClose }) {
  if (!u) return null;
  return (
    <div className="overlay" onClick={e=>e.target===e.currentTarget&&onClose()}>
      <div className="modal" style={{ maxWidth:500 }}>
        <div className="modal-head">
          <h3>User Profile</h3>
          <button className="btn btn-ghost icon-btn" onClick={onClose}>
            <svg width="15" height="15" fill="none" stroke="currentColor" strokeWidth="2.5" viewBox="0 0 24 24"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
          </button>
        </div>
        <div className="modal-body">
          <div style={{ textAlign:'center', marginBottom:24 }}>
            <div style={{ width:74, height:74, borderRadius:20, background:u.color, display:'flex', alignItems:'center', justifyContent:'center', fontSize:26, fontWeight:700, color:'#fff', margin:'0 auto 12px', boxShadow:`0 6px 20px ${u.color}44` }}>{u.initials}</div>
            <div style={{ fontFamily:"'Space Grotesk',sans-serif", fontSize:21, fontWeight:800, color:'var(--navy)' }}>{u.name}</div>
            <div style={{ fontSize:13, color:'var(--gray-400)', marginTop:3 }}>{String(u.id).slice(-12)}</div>
            <div style={{ marginTop:9 }}><Badge s={u.kyc}/></div>
          </div>

          <div style={{ marginBottom:20 }}>
            <div style={{ fontSize:10.5, fontWeight:700, color:'var(--gray-400)', textTransform:'uppercase', letterSpacing:'0.8px', marginBottom:10, display:'flex', alignItems:'center', gap:7 }}>
              <div style={{ width:22, height:22, borderRadius:6, background:'#EFF6FF', display:'flex', alignItems:'center', justifyContent:'center', fontSize:12 }}>👤</div>
              Personal Details
            </div>
            <div className="detail-grid">
              {[['Email',u.email||'—'],['Phone',u.phone||'—'],['KYC Status',u.kyc],['Joined',u.joined]].map(([l,v])=>(
                <div className="detail-item" key={l}><label>{l}</label><span>{v}</span></div>
              ))}
            </div>
          </div>

          {u.bankDetails && (
            <div>
              <div style={{ fontSize:10.5, fontWeight:700, color:'var(--gray-400)', textTransform:'uppercase', letterSpacing:'0.8px', marginBottom:10, display:'flex', alignItems:'center', gap:7 }}>
                <div style={{ width:22, height:22, borderRadius:6, background:'#F0F9FF', display:'flex', alignItems:'center', justifyContent:'center', fontSize:12 }}>🏦</div>
                Bank Details
              </div>
              <div style={{ border:'2px solid #BAE6FD', borderRadius:14, overflow:'hidden' }}>
                <div style={{ background:'linear-gradient(135deg,#F0F9FF,#E0F2FE)', padding:'12px 16px', display:'flex', alignItems:'center', gap:12, borderBottom:'1px solid #BAE6FD' }}>
                  <div style={{ width:40, height:40, borderRadius:10, background:'rgba(14,165,233,0.15)', display:'flex', alignItems:'center', justifyContent:'center', fontSize:20 }}>🏦</div>
                  <div>
                    <div style={{ fontSize:14, fontWeight:700, color:'var(--navy)' }}>{u.bankDetails.bankName}</div>
                    <div style={{ fontSize:11.5, color:'#0EA5E9', fontWeight:600, marginTop:1 }}>Primary Bank Account</div>
                  </div>
                </div>
                <div style={{ padding:'14px 16px', display:'flex', flexDirection:'column', gap:10 }}>
                  {[['Account Number',u.bankDetails.accountNumber],['IFSC Code',u.bankDetails.ifsc],['Account Holder',u.bankDetails.accountHolder||u.name]].map(([label,value])=>(
                    <div key={label} style={{ display:'flex', justifyContent:'space-between', alignItems:'center', gap:12 }}>
                      <span style={{ fontSize:12, color:'var(--gray-400)', fontWeight:500, flexShrink:0 }}>{label}</span>
                      <span style={{ fontSize:12, fontWeight:700, color:'var(--navy)', fontFamily:(label==='Account Number'||label==='IFSC Code')?'monospace':'inherit', textAlign:'right' }}>{value}</span>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          )}
        </div>
        <div className="modal-foot">
          <button className="btn btn-outline" onClick={onClose}>Close</button>
        </div>
      </div>
    </div>
  );
}

export default function Users() {
  const [users, setUsers]   = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [fKYC, setFKYC]     = useState('All');
  const [sel, setSel]       = useState(null);
  const [page, setPage]     = useState(1);
  const navigate = useNavigate();
  const per = 8;

  useEffect(() => {
    getAllSubmissions()
      .then(res => {
        const arr = res.data?.data || res.data?.submissions || res.data || [];
        const normalized = (Array.isArray(arr) ? arr : []).map((r, idx) => {
          const name    = r.userName || r.name || r.user?.name || 'Unknown';
          const docs    = r.documents || {};
          const bank    = docs.bankDocs?.cancelCheque || null;
          return {
            id:       r.userId   || r._id  || r.id || '',
            name,
            email:    r.email    || r.user?.email    || r.userEmail    || '—',
            phone:    r.phone    || r.user?.phone    || r.userPhone    || '—',
            kyc:      normalizeStatus(r.status || r.kycStatus),
            wallet:   r.walletBalance ? `${r.walletBalance} PYO` : '0 PYO',
            joined:   r.createdAt ? new Date(r.createdAt).toLocaleDateString('en-IN', { day:'2-digit', month:'short', year:'numeric' }) : '—',
            initials: getInitials(name),
            color:    COLORS[idx % COLORS.length],
            bankDetails: bank ? {
              bankName:      bank.bankName,
              accountNumber: bank.accountNumber,
              ifsc:          bank.ifsc,
              accountHolder: bank.accountHolder || name,
            } : null,
          };
        });
        setUsers(normalized);
      })
      .catch(() => {})
      .finally(() => setLoading(false));
  }, []);

  const filtered = users.filter(u => {
    const mk = fKYC==='All' || u.kyc===fKYC;
    const ms = !search || u.name.toLowerCase().includes(search.toLowerCase()) || u.email.toLowerCase().includes(search.toLowerCase()) || String(u.id).toLowerCase().includes(search.toLowerCase());
    return mk && ms;
  });
  const tp    = Math.max(1, Math.ceil(filtered.length / per));
  const paged = filtered.slice((page-1)*per, page*per);

  const total    = users.length;
  const verified = users.filter(u=>u.kyc==='Approved').length;
  const pending  = users.filter(u=>u.kyc==='Pending').length;

  return (
    <div className="page">
      <style>{`@keyframes shimmer{0%{background-position:200% 0}100%{background-position:-200% 0}}`}</style>
      <div className="page-header">
        <div className="page-header-left"><h2>Users</h2><p>Manage all registered PayO users.</p></div>
        <div style={{ display:'flex', gap:10 }}>
          {[[total,'Total'],[verified,'Verified'],[pending,'Pending']].map(([v,l])=>(
            <div key={l} style={{ background:'#fff', border:'1.5px solid var(--gray-200)', borderRadius:10, padding:'9px 16px', textAlign:'center' }}>
              <div style={{ fontFamily:"'Space Grotesk',sans-serif", fontSize:18, fontWeight:800, color:'var(--navy)' }}>{loading ? '—' : v.toLocaleString()}</div>
              <div style={{ fontSize:11, color:'var(--gray-400)', fontWeight:600 }}>{l}</div>
            </div>
          ))}
        </div>
      </div>

      <div className="card">
        <div className="filter-bar">
          <div className="search-field">
            <svg width="14" height="14" fill="none" stroke="var(--gray-400)" strokeWidth="2" viewBox="0 0 24 24"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>
            <input placeholder="Search by name, email or ID..." value={search} onChange={e=>{setSearch(e.target.value);setPage(1);}}/>
          </div>
          <select className="filter-select" value={fKYC} onChange={e=>{setFKYC(e.target.value);setPage(1);}}>
            {['All','Pending','In Review','Approved','Failed'].map(s=><option key={s}>{s}</option>)}
          </select>
          <div className="filter-count">{filtered.length} users</div>
        </div>

        <div className="table-wrap">
          <table>
            <thead><tr><th>User</th><th>Email</th><th>Phone</th><th>KYC</th><th>Wallet</th><th>Joined</th><th>Actions</th></tr></thead>
            <tbody>
              {loading
                ? Array(6).fill(0).map((_,i)=>(
                    <tr key={i}>
                      <td><div style={{ display:'flex', alignItems:'center', gap:10 }}><Skeleton w={34} h={34} radius={8}/><div><Skeleton w={100} h={12} radius={4} style={{ marginBottom:4 }}/><Skeleton w={70} h={10} radius={4}/></div></div></td>
                      <td><Skeleton w={140} h={12} radius={4}/></td>
                      <td><Skeleton w={100} h={12} radius={4}/></td>
                      <td><Skeleton w={70} h={22} radius={20}/></td>
                      <td><Skeleton w={60} h={12} radius={4}/></td>
                      <td><Skeleton w={80} h={12} radius={4}/></td>
                      <td><Skeleton w={60} h={28} radius={8}/></td>
                    </tr>
                  ))
                : paged.map(u=>(
                    <tr key={u.id}>
                      <td>
                        <div className="user-cell">
                          <div className="avatar" style={{ background:u.color }}>{u.initials}</div>
                          <div><div className="uname">{u.name}</div><div className="uid">{String(u.id).slice(-10)}</div></div>
                        </div>
                      </td>
                      <td style={{ fontSize:13, color:'var(--gray-600)' }}>{u.email}</td>
                      <td style={{ fontSize:13, color:'var(--gray-600)' }}>{u.phone}</td>
                      <td><Badge s={u.kyc}/></td>
                      <td style={{ fontWeight:600, color:u.wallet==='0 PYO'?'var(--gray-400)':'var(--green)' }}>{u.wallet}</td>
                      <td style={{ fontSize:13, color:'var(--gray-400)' }}>{u.joined}</td>
                      <td>
                        <div className="act-group">
                          <button className="btn btn-outline" style={{ fontSize:12, padding:'5px 11px' }} onClick={()=>setSel(u)}>View</button>
                          {(u.kyc==='Pending'||u.kyc==='In Review')&&(
                            <button className="btn btn-outline" style={{ fontSize:12, padding:'5px 11px' }} onClick={()=>navigate('/kyc')}>KYC</button>
                          )}
                        </div>
                      </td>
                    </tr>
                  ))
              }
            </tbody>
          </table>
          {!loading && paged.length===0 && <div className="empty">No users found.</div>}
        </div>

        {!loading && (
          <div className="pagination">
            <div className="pag-info">Showing {Math.min((page-1)*per+1,filtered.length)}–{Math.min(page*per,filtered.length)} of {filtered.length}</div>
            <div className="pag-btns">
              <button className="pag-btn" disabled={page===1} onClick={()=>setPage(p=>p-1)}>‹</button>
              {Array.from({length:tp},(_,i)=>(<button key={i+1} className={`pag-btn${page===i+1?' act':''}`} onClick={()=>setPage(i+1)}>{i+1}</button>))}
              <button className="pag-btn" disabled={page===tp} onClick={()=>setPage(p=>p+1)}>›</button>
            </div>
          </div>
        )}
      </div>
      {sel && <UserModal u={sel} onClose={()=>setSel(null)}/>}
    </div>
  );
